using Hangfire;
using Microsoft.EntityFrameworkCore;
namespace Zyven.Infrastructure;

public sealed class PixRecoveryWorker(ZyvenDbContext db, ITransactionalEmail email, ITelegramClient telegram, TelegramCredentialVault vault, TimeProvider time)
{
    [DisableConcurrentExecution(timeoutInSeconds: 60)] public async Task Run(CancellationToken ct) { var ids = await db.PixRecoveryExecutions.AsNoTracking().Where(x => x.Status == "SCHEDULED" && x.NextRunAt <= time.GetUtcNow()).OrderBy(x => x.NextRunAt).Select(x => x.Id).Take(100).ToListAsync(ct); foreach (var id in ids) await Process(id, ct); }
    private async Task Process(Guid id, CancellationToken ct) { await using var tx = await db.Database.BeginTransactionAsync(ct); var e = await db.PixRecoveryExecutions.FromSqlInterpolated($"SELECT * FROM \"PixRecoveryExecutions\" WHERE \"Id\"={id} FOR UPDATE").SingleOrDefaultAsync(ct); if (e is null || e.Status != "SCHEDULED" || e.NextRunAt > time.GetUtcNow()) { await tx.CommitAsync(ct); return; } var p = await db.Payments.FromSqlInterpolated($"SELECT * FROM \"Payments\" WHERE \"Id\"={e.PaymentId} FOR UPDATE").SingleAsync(ct); var checkout = await db.Checkouts.SingleAsync(x => x.Id == p.CheckoutSessionId, ct); if (p.Status != "PENDING" || p.ExpiresAt <= time.GetUtcNow() || checkout.Status != "CREATED") { e.Status = p.Status == "PAID" ? "COMPLETED_PAYMENT" : "COMPLETED_TERMINAL"; e.CompletedAt = e.UpdatedAt = time.GetUtcNow(); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return; } var msg = await db.PixRecoveryMessages.AsNoTracking().SingleAsync(x => x.ConfigurationId == e.ConfigurationId && x.Version == e.Version && x.Position == e.CurrentPosition, ct); var attempt = await db.PixRecoveryAttempts.SingleOrDefaultAsync(x => x.ExecutionId == e.Id && x.Position == e.CurrentPosition, ct); if (attempt?.Status == "SENT") { await Advance(e, ct); await tx.CommitAsync(ct); return; } attempt ??= new() { OrganizationId = e.OrganizationId, ExecutionId = e.Id, Position = e.CurrentPosition, Channel = e.Channel, CreatedAt = time.GetUtcNow() }; if (db.Entry(attempt).State == EntityState.Detached) db.Add(attempt); attempt.TryCount++; attempt.Status = "RESERVED"; await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); var offer = await db.Offers.AsNoTracking().SingleAsync(x => x.Id == p.OfferId, ct); var text = Expand(e.Channel == "TELEGRAM" ? msg.TelegramText : msg.EmailText, checkout, offer, p); try { if (e.Channel == "TELEGRAM") { var binding = await db.BotCheckoutBindings.AsNoTracking().SingleAsync(x => x.CheckoutId == checkout.Id, ct); var i = await db.TelegramIntegrations.AsNoTracking().SingleAsync(x => x.Id == binding.TelegramIntegrationId && x.OrganizationId == e.OrganizationId, ct); var token = vault.Decrypt(new(i.TokenCiphertext, i.TokenNonce, i.TokenTag, i.TokenFingerprint)); await telegram.SendMessage(token, binding.TelegramUserId, text, ct); } else await email.Send(checkout.Email, $"Seu PIX de {offer.Name} está aguardando pagamento", text, ct); attempt.Status = "SENT"; attempt.SentAt = time.GetUtcNow(); await Advance(e, ct); } catch (Exception) { attempt.Status = attempt.TryCount >= 3 ? "FAILED" : "RETRY"; if (attempt.TryCount >= 3) { e.Status = "FAILED"; e.CompletedAt = time.GetUtcNow(); } else e.NextRunAt = time.GetUtcNow().AddMinutes((int)Math.Pow(5, attempt.TryCount)); e.UpdatedAt = time.GetUtcNow(); } await db.SaveChangesAsync(ct); }
    private async Task Advance(Zyven.Domain.PixRecoveryExecution e, CancellationToken ct) { e.CurrentPosition++; var next = await db.PixRecoveryMessages.AsNoTracking().Where(x => x.ConfigurationId == e.ConfigurationId && x.Version == e.Version && x.Position == e.CurrentPosition).SingleOrDefaultAsync(ct); if (next is null) { e.Status = "COMPLETED"; e.CompletedAt = time.GetUtcNow(); } else { var p = await db.Payments.AsNoTracking().SingleAsync(x => x.Id == e.PaymentId, ct); e.NextRunAt = p.CreatedAt.AddMinutes(next.DelayMinutes); } e.UpdatedAt = time.GetUtcNow(); }
    private static string Expand(string s, Zyven.Domain.CheckoutSession c, Zyven.Domain.Offer o, Zyven.Domain.Payment p) => s.Replace("{{buyer_name}}", c.Name, StringComparison.Ordinal).Replace("{{offer_name}}", o.Name, StringComparison.Ordinal).Replace("{{amount}}", p.GrossAmount.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture), StringComparison.Ordinal).Replace("{{pix_expiry}}", p.ExpiresAt.ToString("dd/MM/yyyy HH:mm", System.Globalization.CultureInfo.GetCultureInfo("pt-BR")), StringComparison.Ordinal).Replace("{{pix_code}}", p.PixCode ?? "", StringComparison.Ordinal).Replace("{{checkout_url}}", $"/checkout/{c.Id}", StringComparison.Ordinal);
}
